// Buttons in the summary should not inherit the eyebrow's mono uppercase.
rep(`<summary className="cursor-pointer list-none eyebrow flex items-center gap-1.5 [&::-webkit-details-marker]:hidden"><ChevronRight className="size-3.5 transition-transform group-open:rotate-90" aria-hidden="true" />{KIND_LABELS[kind]} ({manual.filter(item => item.kind === kind).length})`,
