const inner = block.replace(`    {run.tasks.length > 0 && <h2 className="eyebrow">How the team worked</h2>}\n`, "").replace(/^    /gm, "    ");
rep(`  return <div className="space-y-6">`, `  const team = <>\n    {!active && run.tasks.length > 0 && <h2 className="eyebrow">How the team worked</h2>}\n${inner}  </>;\n\n  return <div className="space-y-6">`);
rep(`    {run.error && <p role="alert"`, `    {active && team}\n    {run.error && <p role="alert"`);
fs.writeFileSync(f, s.replace(/\n/g, eol));
EOF
