cd /c/Users/mgsuk/.t3/worktrees/Moneo/t3-80f94ba4; cat > /tmp/sel.mjs <<'EOF'
import fs from "node:fs";
const f = "lib/ai/selected-conversation.ts";
let s = fs.readFileSync(f, "utf8");
const a = `/** Session cookie: the open chat resumes in this browser session only; a new session starts on an empty chat. */
export function selectConversation(key: string, id: string, notify = true) {
  document.cookie = \`\${key}=\${encodeURIComponent(id)}; Path=/; SameSite=Lax\${location.protocol === "https:" ? "; Secure" : ""}\`;`;
const b = `// Browsers that restore the last session keep session cookies indefinitely, so the choice also lapses after this long idle.
export const SELECTION_IDLE_SECONDS = 30 * 60;

/** The open chat resumes while you keep using Moneo; coming back later starts on an empty chat, like a fresh session. */
export function selectConversation(key: string, id: string, notify = true) {
  document.cookie = \`\${key}=\${encodeURIComponent(id)}; Path=/; Max-Age=\${SELECTION_IDLE_SECONDS}; SameSite=Lax\${location.protocol === "https:" ? "; Secure" : ""}\`;`;
const crlf = s.includes("\r\n"); s = s.replace(/\r\n/g, "\n");
if (!s.includes(a)) throw new Error("no match");
s = s.replace(a, b);
fs.writeFileSync(f, crlf ? s.replace(/\n/g, "\r\n") : s);
EOF
node /tmp/sel.mjs && cat > lib/ai/selected-conversation.test.ts <<'EOF'
// @vitest-environment jsdom
import { expect, it, vi } from "vitest";
import { SELECTION_IDLE_SECONDS, selectConversation } from "./selected-conversation";

it("remembers the open chat only for an idle window, so a later visit starts a new chat", () => {
  const set = vi.spyOn(document, "cookie", "set");
  selectConversation("moneo-conversation-w", "abc", false);
  expect(set).toHaveBeenCalledWith(`moneo-conversation-w=abc; Path=/; Max-Age=${SELECTION_IDLE_SECONDS}; SameSite=Lax`);
});
EOF
npx vitest run lib/ai/selected-conversation.test.ts 2>&1 | grep -E "Tests|FAIL|Error" | head

